def katapayadi_test():
    def split_phonetic_syllables(txt):
        stop = '्'
        cluster = ''
        end = None

        for char in txt:
            category = unicodedata.category(char)
            # Check if the character is a base letter followed by a virama (halant), or a combining mark
            if (category == 'Lo' and end == stop) or category[0] == 'M':
                cluster = cluster + char
            else:
                if cluster:
                    yield cluster
                cluster = char
            end = char

        if cluster:
            yield cluster

    # Example Usage
    word = "राम" # र = 2, म = 5 => Read backwards = 52
    number = decode_katapayadi(word)
    print(f"The Katapayadi value for '{word} {mytrans.transliterate(word,'kannada')}' is: {number}")
    word = "ರಾಮ"
    print(f"The Katapayadi value for '{word} {mytrans.transliterate(word)}' is: {number}")

    # Test string: "धर्मक्षेत्रे"
    text = "धर्मक्षेत्रे"
    # syllables = split_devanagari_clusters(text)
    # print(syllables)
    # Output: ['ध', 'र्म', 'क्षे', 'त्रे']
    syllables = list(split_phonetic_syllables(text))
    print(syllables)
    # Output: ['ध', 'र्', 'म', 'क्षे', 'त्', 'रे']

    for k in ragaDevanagari.keys():
        syllables = list(split_phonetic_syllables(k))
        res = decode_katapayadi(''.join(syllables[:2]))
        print(f'{k} {syllables} {res}')
