def print_ragas_in_columns():
    shuddha, prati = [], []
    for iast, v in ragaIast.items():
        if iast == '': continue
        devanagari, kannada, itrans, chakra, nr = v['devanagari'], v['kannada'], v['ITRANS'], v['chakra'], v['number']
        scale = get_scale(nr)  #v['scale'],
        # katapayadi = decode_katapayadi(devanagari[:2])
        # line = f'{iast:29s} {scale}{' ' * 4}{' '.join(scale.split(' '))}{' ' * 7}{itrans:19s}{" " * 16}{chakras.index(chakra) + 1}. {chakra}{' ' * 12}{katapayadi}-{devanagari}{" " * 16} {kannada}'
        line = f'{iast:29s} {scale}{' ' * 4} S {' '.join(scale.split(' ')[::-1][:-1])}{' ' * 12}{itrans:19s}{" " * 13}{chakras.index(chakra) + 1}. {chakra}{' ' * 12}{devanagari}{" " * 16} {kannada}'
        if nr <= 36: shuddha.append(line)
        else: prati.append(line)
    print(f'name{" " * 32} arohana{" " * 15}avaorohana{" " * 16}itrans{" " * 25}chakra{' ' * 11}devanagari{" " * 13}kannada\n{"-" * 27} {"-" * 23} {"-" * 23}{' ' * 6}{"-" * 23}{' ' * 9}{"-" * 12}{' ' * 6}{"-" * 16}{' ' * 6}{"-" * 16}')
    for line in shuddha + prati: print(line)
def get_scale(num: int):
    if 1 <= num <= 72:
        num -= 1
        # chakra = chakras[num // 6]
        ma = ['M₁', 'M₂'][num // 36]
        by6, by6chakra_ga, by3chakra_ri = num % 6, (num // 6) % 6, (num // 6) % 6
        ni = ['N₁', 'N₂', 'N₃', 'N₂', 'N₃', 'N₃'][by6]
        # da = 'D₁' if by < 3 else 'D₂' if by3 < 6 else 'D₃'
        da = ['D₁', 'D₁', 'D₁', 'D₂', 'D₂', 'D₃'][by6]
        ga = ['G₁', 'G₂', 'G₃', 'G₂', 'G₃', 'G₃'][by6chakra_ga]
        # ri = 'R₁'if by3chakra_ri < 3 else 'R₂' if by3chakra_ri < 6 else 'R₃'
        ri = ['R₁', 'R₁', 'R₁', 'R₂', 'R₂', 'R₃'][by6chakra_ga]
        return f'S {ri} {ga} {ma} P {da} {ni}'
    else: raise ValueError(f'raga no. {num} invalid')

